// `pnpm fin tunnel create <env> <public|admin>` (spec 01 §7.3, [FD-13], EXECUTION §2.5 step 4):
// makes the tunnel locally managed (`config_src: local`, so no remote configuration applies), then
// fetches its token and sets it as the sealed TUNNEL_TOKEN of its one connector service, with the
// plain FIN_TUNNEL_ROLE and FIN_TUNNEL_HOSTS the supervisor renders its ingress map from. The
// token is never printed; the standby `-b` services get no token. Escrow comes first in the plan
// (ARCHITECTURE §6.10); staging has no escrow recipient yet (BD-14), so the token is regenerated by
// recreating the tunnel if it is ever lost (docs/runbooks/rotate-tunnel-token.md).

import type { Command } from "../command.ts";
import { RefusedError } from "../core/errors.ts";
import { hostOf } from "../core/overlay.ts";
import type { Change } from "../core/plan.ts";
import { Secret } from "../core/secret.ts";
import type { TunnelRole } from "../core/settings.ts";
import { cloudflare, findTunnel, railway, type Tunnel } from "./common.ts";

export const tunnelCreate: Command = {
  words: ["tunnel", "create"],
  summary: "create a locally managed tunnel and set its token sealed on its connector service",
  positionals: [{ name: "role", description: "which tunnel", values: ["public", "admin"] }],
  flags: [],
  overlay: true,
  mutating: true,
  runbook: "tunnel-create.md",
  async run(ctx) {
    const role = ctx.args.positionals[0] as TunnelRole;
    const t = ctx.settings.tunnels[role];
    ctx.guard.checkOwnName(t.name, "tunnel");
    const { api, writer, accountPath } = cloudflare(ctx);
    const rw = railway(ctx);
    await rw.serviceId(t.connector);
    let tunnel: Tunnel | undefined = await findTunnel(ctx, api, role);
    const hostMap = Object.fromEntries(t.ingress.map((r) => [r, hostOf(ctx.overlay, r)]));
    for (const host of Object.values(hostMap)) ctx.guard.checkName(host, `tunnel ${t.name}`);

    const changes: Change[] = [
      {
        kind: "tunnel",
        name: t.name,
        action: tunnel === undefined ? "create" : "keep",
        detail: "locally managed (config_src local)",
      },
      {
        kind: "variables",
        name: t.connector,
        action: "update",
        detail:
          "TUNNEL_TOKEN (sealed, fetched from Cloudflare, never printed), FIN_TUNNEL_ROLE, FIN_TUNNEL_HOSTS",
      },
    ];
    const create = { name: t.name, config_src: "local" };
    return ctx.applyPlan(
      `tunnel ${role}`,
      changes,
      async (change) => {
        if (change.kind === "tunnel") {
          tunnel = await writer.write<Tunnel>(
            { kind: "tunnel", name: t.name },
            "POST",
            `${accountPath}/cfd_tunnel`,
            create,
          );
          ctx.masker.register(tunnel.id, `<tunnel:${role}>`);
          return;
        }
        if (tunnel === undefined) throw new Error("the tunnel was not created");
        const raw = await api.get<string>(`${accountPath}/cfd_tunnel/${tunnel.id}/token`);
        if (typeof raw !== "string" || raw.length < 20)
          throw new Error("Cloudflare answered no tunnel token");
        ctx.masker.register(raw, "<tunnel-token>");
        const token = new Secret(raw);
        await rw.setVariables(
          ctx.run,
          ctx.settings,
          t.connector,
          { TUNNEL_TOKEN: token, FIN_TUNNEL_ROLE: role, FIN_TUNNEL_HOSTS: JSON.stringify(hostMap) },
          `pnpm fin tunnel create ${role} (${ctx.run.id})`,
        );
      },
      {},
      {
        check: (change) => {
          if (change.kind === "tunnel") {
            writer.check(
              { kind: "tunnel", name: t.name },
              "POST",
              `${accountPath}/cfd_tunnel`,
              create,
            );
          } else if (ctx.settings.railway.services[t.connector] === undefined) {
            throw new RefusedError(
              `railway: ${t.connector} is not a service the public settings list`,
            );
          }
        },
      },
    );
  },
};
